const job = Array.isArray($json) ? $json[0] : $json;
const input = job.input || {};

return [{
  json: {
    jobId: job.job_id,
    projectName: input.projectName,
    status: job.status,
    files: input.files || {},
    projectId: job.project_id || null,
    requestedBy: job.requested_by || null,
    settingsVersion: job.settings_version || null,
    configSnapshot: job.config_snapshot || {},
    processingStartedAt: job.updated_at || new Date().toISOString()
  }
}];

function encodeUrlPathSegments(value) {
  const text = String(value || '').trim();
  if (!text) return text;
  const match = text.match(/^([a-z][a-z0-9+.-]*:\/\/[^/?#]+)(\/[^?#]*)([?#].*)?$/i);
  const encodeSegment = segment => {
    if (!segment) return segment;
    try { return encodeURIComponent(decodeURIComponent(segment)); }
    catch { return encodeURIComponent(segment); }
  };
  if (!match) return text.split('/').map(encodeSegment).join('/');
  return match[1] + match[2].split('/').map(encodeSegment).join('/') + (match[3] || '');
}

const files = $json.files || {};

return Object.entries(files).map(([key, url]) => {
  return {
    json: {
      fileKey: key,
      fileUrl: encodeUrlPathSegments(url),
      projectName: $json.projectName,
      status: $json.status,
      jobId: $json.jobId,
      projectId: $json.projectId || null,
      requestedBy: $json.requestedBy || null,
      settingsVersion: $json.settingsVersion || null,
      configSnapshot: $json.configSnapshot || {},
      processingStartedAt: $json.processingStartedAt || null
    }
  };
});

const allItems = $input.all();

let combinedBinary = {};
let combinedJson = [];

allItems.forEach((item, index) => {
  combinedJson.push(item.json);
  if (item.binary && item.binary.data) {
    combinedBinary['data' + index] = item.binary.data;
  }
});

const first = allItems[0]?.json || {};

return [
  {
    json: {
      files: combinedJson,
      jobId: first.jobId,
      projectName: first.projectName,
      status: first.status,
      projectId: first.projectId || null,
      requestedBy: first.requestedBy || null,
      settingsVersion: first.settingsVersion || null,
      configSnapshot: first.configSnapshot || {},
      processingStartedAt: first.processingStartedAt || null
    },
    binary: combinedBinary
  }
];

const data = $json;

// âœ… Extract keys from files object
const fileKeys = Object.keys(data.files || {});
const totalFiles = fileKeys.length;

console.log("ðŸš€ PROCESSING STARTED:", {
  jobId: data.jobId,
  projectName: data.projectName,
  totalFiles,
  fileKeys
});

return [
  {
    json: {
      jobId: data.jobId,
      projectName: data.projectName,
      totalFiles,
      fileKeys,
      logType: "PROCESSING_STARTED"
    }
  }
];

const source = $('Convert ALL binaries inside ONE item').first().json || {};

function clean(value, fallback = '') {
  if (value === null || value === undefined) return fallback;
  if (typeof value === 'string') return value.trim() || fallback;
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function pickMessage(json) {
  return clean(
    json.error?.message ||
    json.errorMessage ||
    json.message ||
    json.description ||
    'Ingestion vectorization failed before chunks could be stored in ChromaDB'
  );
}

return $input.all().map((item) => {
  const json = item.json || {};
  const output = json.output || {};
  const tokenUsage = json.tokenUsage || output.tokenUsage || {};
  const message = pickMessage(json);
  return {
    json: {
      jobId: clean(source.jobId || json.jobId),
      projectName: clean(source.projectName || json.projectName),
      projectId: clean(source.projectId || json.projectId),
      requestedBy: clean(source.requestedBy || json.requestedBy),
      settingsVersion: source.settingsVersion ?? json.settingsVersion ?? null,
      failureStage: json.failureStage || output.failureStage || 'full_ingest_vectorization_subworkflow',
      source: json.source || output.source || 'fullIngestDraft01',
      message,
      wordCount: Number(json.wordCount || output.wordCount || tokenUsage.embeddedWordCount || 0) || 0,
      totalChunksStored: Number(json.totalChunksStored || output.totalChunksStored || json.chunkCount || output.chunkCount || 0) || 0,
      chunkCount: Number(json.chunkCount || output.chunkCount || json.totalChunksStored || output.totalChunksStored || 0) || 0,
      tokensInput: Number(json.tokensInput || output.tokensInput || tokenUsage.tokensInput || 0) || 0,
      tokensOutput: Number(json.tokensOutput || output.tokensOutput || tokenUsage.tokensOutput || 0) || 0,
      tokensTotal: Number(json.tokensTotal || output.tokensTotal || tokenUsage.tokensTotal || 0) || 0,
      estimatedCostUsd: Number(json.estimatedCostUsd || output.estimatedCostUsd || tokenUsage.estimatedCostUsd || 0) || 0,
      tokenUsage: Object.keys(tokenUsage).length ? tokenUsage : {
        accounting: 'failed_ingestion_no_token_usage_available',
        tokensInput: 0,
        tokensOutput: 0,
        tokensTotal: 0,
        estimatedCostUsd: 0
      },
      extractionObservability: json.extractionObservability || output.extractionObservability || {},
      errorDetails: json.errorDetails || json.error || null,
      timestamp: new Date().toISOString()
    }
  };
});

